#!/usr/bin/env python3
"""Human-readable companion generated from exactly the same battle catalogue."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
def main():
    c=json.loads((ROOT/'prototypes/prepared-encounters/perelomye/catalog.json').read_text())
    lines=['# Переломье: подготовка противников',
      '', 'Дата: 28 октября 2026. Только для ведущего: ниже есть сведения о непосещённых местах.',
      '', 'Подготовка, не сыгранное событие. Текущая сцена, ревизия канона, время и ресурсы не изменяются.',
      '', '19 готовых профилей, 13 шаблонов комнат, 11 расстановок для репетиций. L5 и условный конфликт V4 требуют фактических позиций. Три полных досье боссов сохранены вместе с их календарями, целями, уликами, мирными вариантами, отходом и восстановлением.',
      '', 'Режим — с решениями ведущего. Штатный SDK исполняет обычный бой, дополнение — подготовленные действия и учёт. Объёмный полёт, цели областей, инициатива 20, приборы и окно контрмагии авторских заклинаний требуют явного подтверждения. Это не заявляется полностью автоматической симуляцией.',
      '', 'Запуск и ограничения: [инструкция](../prototypes/prepared-encounters/README.md).',
      '', '## Охват', '', '| Участок | Подготовка | Ограничение |', '|---|---|---|',
      '| G | C09, C10, C11, общие мирные C03/C04 | G5 уже готовится в другом чате; не пересоздавать |',
      '| T3, T5, T7–T8 | C12, C29, C32, четыре C36 | T5 отделён 4 минутами; T4–T7 — 20 минут |',
      '| L1, L3, L5 | C05, C04, C03 | Четыре стража всего; L5 — другая смена |',
      '| P8–P9 | C34, два C37 | Право доступа может решить сцену без боя |',
      '| B7–B8 | C33, опоры и грозовая среда | Проверить охотничий календарь; новых детёнышей нет |',
      '| Условное «Право на дорогу» | C23, C24, C26, два C05_company, C03/C04 | Только реальные события, люди и остаток бюджета §11.3 |',
      '| Уже известные C14/C18 | Переиспользуемые карточки | Не создавать новые экземпляры |',
      '| S, K, N, X, пройденные B1–B6, отдельная Серая штольня | Не вводятся заново | Вне подготовки непосещённых ветвей текущего мира |',
      '', '## Точные боевые карточки', '', '| ID | Существо | ПЗ | КД | Площадь |', '|---|---|---:|---:|---:|']
    for key,p in c['profiles'].items():lines.append(f"| {key} | {p['name']} | {p['hp']} | {p['ac']} | {p.get('footprint',1)}×{p.get('footprint',1)} |")
    lines+=['', 'Модификаторы, спасброски, навыки, чувства и защиты сохранены. Исходник задаёт модификаторы, поэтому числовые scores — представитель с тем же модификатором, не найденная задним числом характеристика. Явные значения спасбросков и навыков имеют приоритет.',
      '', 'C05_company — единственная новая разновидность в подготовке: те же боевые числа C05, Общий язык, договорная мотивация и обычный конечный комплект. Это два уже предусмотренных охранника компании, не прибавка к численности.',
      '', '## Исполнение и решения ведущего', '', '| Механика | Готово в загрузчике | Что подтверждает ведущий |','|---|---|---|',
      '| Обычный бой и классы героев | Штатное ядро и нынешний снимок четырёх героев | Реальная расстановка, расходы перед стартом |',
      '| Урон разных типов | Отдельные компоненты, критические кости, защиты | Ситуационные условия источника |',
      '| Рой | Общее пространство, ослабление при 18 ПЗ, яд до конца следующего хода | Улей, преследование, дым |',
      '| Пылееды и комок | Заряд пыли, облако, кислотный урон, захват | Щели, высота колодца, закрываемая дверь |',
      '| Легендарные способности | Очки, окно после чужого хода, одна способность, отдельная реакция подчинённого | Законность цели и траектории |',
      '| Устойчивость | Окно после провала, конечное применение, ПЗ/прибор как цена | Какой работающий прибор сжечь |',
      '| Фазы | В начале следующего своего хода, без лечения/перезарядки | Последствия ручного подавления приборов |',
      '| Оболочки | Четыре исходных экземпляра, личная инициатива, активация со следующего раунда | Условия прекращения обета |',
      '| Дыхание | Заряды, запрет без объявления, запись подготовки, перезарядка у опор | Ось, поворот ≤45°, сдвиг ≤10 фт, конус |',
      '| Арена | Источник, задержка полного цикла, отмена при отключении, броски и урон | Инициатива 20, область/полоса, укрытия, заземление |',
      '| Авторские заклинания | Применения, действие, спасброски/урон/состояние | Компоненты, контрмагия, Тишина, Сфера; отменённый эффект не применять |',
      '| Полёт | Различимые токены, режим скорости, явная высота в расстоянии | 3D видимость, падение, выход за экран, допустимый маршрут |',
      '', '## Истории и условия встречи боссов']
    for b in c['bosses'].values():
        lines+=['', '### '+b['name']]
        for key,label in [('history','История'),('clock','Календарь'),('clues','Предвестники'),('behavior','Мотивация и выбор целей'),('alternatives','Другие решения'),('retreat','Отход и восстановление'),('outcome','Исход'),('rewards','Награды')]:
            value=b[key];lines+=['', '**'+label+'.** '+(value if isinstance(value,str) else json.dumps(value,ensure_ascii=False))]
    lines+=['', '## Продолжение и награды', '', 'Держать полное сохранение встречи. Возвращение не лечит существ, не возвращает заряды, погибших стражей или разрушенные приборы. Боевой отчёт и сюжетный исход проверяются отдельно. Применять только подтверждённый результат реального story-боя через штатную транзакцию; репетиция не канон.',
      '', 'Опыт за отдельного босса и суммарный опыт встречи со свитой — альтернативные представления одной суммы. Добыча имеет владельцев, условия выдачи и конечный остаток; здесь она не начисляется.',
      '', '## Проверяемые файлы', '', '- `catalog.json`: единый источник карточек и встреч.', '- `gm-assist.js`, `gm-panel.js`: общее дополнение и панель ведущего.', '- `build_prepared_encounter.py`: загрузка актуальной партии и сборка одного офлайн-файла.', '- `verify_prepared_encounters.py`, `test_prepared_encounters.js`: проверка карточек, механик, очередей и неизменности канона.', '', 'Автоматические проверки не заменяют визуальное тестирование интерфейса и решение ведущего о сложной пространственной ситуации.']
    (ROOT/'docs/PERELOMYE_COMBAT_PREPARATION.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
